/* ===== v1.1: homework toggle memory, live design preview, certificates, updates ===== */
window.HWO=new Set();
document.addEventListener('toggle',e=>{ const d=e.target; if(d&&d.classList&&d.classList.contains('rp-hwd')){ if(d.open) window.HWO.add(d.dataset.hw); else window.HWO.delete(d.dataset.hw); } },true);

let RP_DRAFT=null;
function rpDesignPv(){
  const el=$('rpDesignPv'); if(!el) return; let m;
  try{ m=rpModel(rpCur()); if(!(m.notes.length||m.hw.length)) m=rpSample(); }catch(e){ m=rpSample(); }
  let tp=null; if(RP_DRAFT){ tp=Object.assign({},RP_DRAFT,{f:lsGet('lp.rep.font')||'',af:lsGet('lp.rep.afont')||''}); }
  el.innerHTML=rpHTML(m,tp);
}
(function(){ const f=rpApplyDesign; rpApplyDesign=function(){ const r=f.apply(this,arguments); try{ rpDesignPv(); }catch(e){} return r; }; })();
(function(){ const f=rpPick; rpPick=function(){ RP_DRAFT=null; return f.apply(this,arguments); }; })();
(function(){ const f=rpTSave; rpTSave=function(){ const r=f.apply(this,arguments); RP_DRAFT=null; try{ rpDesignPv(); }catch(e){} return r; }; })();
['input','change'].forEach(ev=>document.addEventListener(ev,e=>{
  const id=e.target&&e.target.id;
  if(['rpCg','rpCg2','rpCgold','rpCbg','rpTLay'].includes(id)){
    RP_DRAFT={lay:$('rpTLay').value,g:$('rpCg').value,g2:$('rpCg2').value,gold:$('rpCgold').value,bg:$('rpCbg').value}; rpDesignPv();
  }
}));

