const CT=Object.assign({name:'',kind:'surah',surah:'',juz:'1',verb:'mem',gender:'m',custEn:'',custAr:'',grade:'ex',date:'',lang:'both',design:'royal',c1:'',c2:'',teacher:'',academy:'',font:'',afont:'',bg:'',tx:'',tEn:'',tAr:'',pEn:'',pAr:'',nobis:'',bisTxt:'',sealIcon:'',sealTxt:'',noseal:'',tl:'',dl:'',msg:'',dua:'auto'},rpJ('lp.cert',{}));
