function ctStack(f){ return f?"'"+f+"',":''; }
function ctWhat(c){
  const si=(+c.surah||0)-1, sEn=RP_SURAHS[si]?RP_SURAHS[si][0]:'…', sAr=RP_SURAHS_AR[si]||'…', f=c.gender==='f';
  const V={mem:['for successfully memorising','لإتمام'+(f?'ها':'ه')+' حفظ'],rec:['for successfully completing the recitation of','لإتمام'+(f?'ها':'ه')+' تلاوة'],rev:['for successfully completing the revision of','لإتمام'+(f?'ها':'ه')+' مراجعة']}[c.verb]||['',''];
  if(c.kind==='surah') return {t:['Certificate of Completion','شهادة إتمام'],en:V[0]+' Surah '+sEn,ar:V[1]+' سورة '+sAr};
  if(c.kind==='juz') return {t:['Certificate of Completion','شهادة إتمام'],en:V[0]+' Juz’ '+(c.juz||'1'),ar:V[1]+' الجزء '+(c.juz||'1')};
  if(c.kind==='quran') return {t:['Certificate of Completion','شهادة إتمام'],en:V[0]+' the entire Holy Qur’an',ar:V[1]+' القرآن الكريم كاملاً'};
  if(c.kind==='noor') return {t:['Certificate of Completion','شهادة إتمام'],en:'for successfully completing the Noor Al-Bayan primer',ar:'لإتمام'+(f?'ها':'ه')+' القاعدة النورانية'};
  if(c.kind==='excel') return {t:['Certificate of Excellence','شهادة تميّز'],en:'for outstanding performance and excellent conduct',ar:f?'لتميّزها وحسن سلوكها':'لتميّزه وحسن سلوكه'};
  return {t:['Certificate of Achievement','شهادة تقدير'],en:c.custEn||'',ar:c.custAr||''};
}
function ctDes(id){ return CT_DES.find(d=>d.id===id)||CT_DES[0]; }
